WITH with_windows AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY segment ORDER BY credit_limit, id) AS row_seq, SUM(credit_limit) OVER (PARTITION BY segment) AS segment_sum_credit_limit, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY country, city), 4) AS credit_limit_share, SUM(credit_limit) OVER (PARTITION BY YEAR(signup_date), city ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_credit_limit, ROW_NUMBER() OVER (PARTITION BY country ORDER BY age, id) AS event_seq FROM customers) SELECT DATE_TRUNC('WEEK', signup_date) AS week_start, country, APPROX_PERCENTILE(segment_sum_credit_limit, 0.5) AS segment_sum_credit_limit_p50, COUNT_IF(country = 'SG') AS sg_events, COUNT(*) AS row_count, RANK() OVER (PARTITION BY DATE_TRUNC('WEEK', signup_date) ORDER BY APPROX_PERCENTILE(segment_sum_credit_limit, 0.5) DESC) AS segment_sum_credit_limit_p50_rank FROM with_windows GROUP BY DATE_TRUNC('WEEK', signup_date), country ORDER BY week_start NULLS LAST
